import pyomo.environ as pyo

DATA = {
    "L_expr_x": {
        "name": "Length of fence wall"
    },
}

DATA = {
    "fence_length": 100.0,
    # supporting-plane data for the area objective (linearisation anchors)
    "c1": 50.0,
    "c2": 100.0,
    "objective_scale": 1.0,
    "parentesis_name_a": 0.0,
    "objetivo_dictump": {
        "compensa_aumento": {
            "obj_const": 0.0,
        }
    }
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.set_ext_indices_helper = pyo.Set(initialize=[1])

    model.x = pyo.Var(domain=pyo.NonNegativeReals,
                      bounds=(0.0, d["fence_length"]))
    model.y = pyo.Var(domain=pyo.NonNegativeReals,
                      bounds=(0.0, d["fence_length"]))

    model.area_support = pyo.Var(domain=pyo.NonNegativeReals)

    def constraint_rule_fencing_budget(m):
        return m.x + 2 * m.y <= d["fence_length"]

    model.constraint_fence_used = pyo.Constraint(rule=constraint_rule_fencing_budget)

    def lp_support_link_name(m):
        return m.area_support <= d["c1"] * m.x + d["c2"] * m.y

    model.constraint_area_link = pyo.Constraint(rule=lp_support_link_name)

    def obj_rule(m):
        return m.area_support * d["objective_scale"]

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    return model
